						     kunit_test_timeout());
	if (time_remaining == 0) {
		kunit_err(test, "try timed out\n");
		try_catch->try_result = -ETIMEDOUT;
		kthread_stop(task_struct);
	}

	exit_code = try_catch->try_result;

	if (!exit_code)
		return;


